def mac_to_modified_eui64(mac):
    b = [int(x, 16) for x in mac.split(':')]  # 6바이트 MAC
    # OUI + FFFE + 장치 ID = 8바이트
    eui = b[0:3] + [0xFF, 0xFE] + b[3:6]
    eui[0] ^= 0x02  # U/L 비트(첫 바이트 7번째 비트) 반전
    groups = []
    for i in range(0, 8, 2):  # 16비트씩 4그룹
        groups.append('%x' % ((eui[i] << 8) | eui[i + 1]))
    return ':'.join(groups)  # 인터페이스 ID (하위 64비트)

def link_local(mac):
    return 'fe80::' + mac_to_modified_eui64(mac)

# link_local('00:1A:2B:3C:4D:5E') → 'fe80::21a:2bff:fe3c:4d5e'
